import React, { useState, useEffect, useRef , Suspense, lazy } from 'react';
import ReactPlayer from 'react-player/lazy'

import { motion } from 'framer-motion';
import { fadeIn } from '../variants';

// import logos
import vegNonVegLogo from '../img/logos/VegNonVeg.png';
import TO6Logo from '../img/logos/Tribeof6.webp'
import demeLogo from '../img/logos/Deme.png'
import ModishLogo from '../img/logos/Modish.png'
import MokobaraLogo from '../img/logos/Mokobara.jpg'
import AsayaLogo from '../img/logos/Asaya.png'
import SimbaLogo from '../img/logos/Simba.png'
import SaykLogo from '../img/logos/Spy Hard Seltzer.png'
import keiflogo from '../img/logos/keif.webp'
import Nail_StationLogo from '../img/logos/Nail station.png'
import SculpLogo from '../img/logos/Sculp tattoos.png'
import DhahiaLogo from '../img/logos/Dhahia juice.png'
import Nothing from '../img/logos/Nothing.png';
import AcquaLogo from '../img/logos/Acqua.png';
import AtyabLogo from '../img/logos/Mello.png';
import ArnavLogo from '../img/logos/Arnav.PNG';

import { paths } from '../components/MediaPaths'; 
// import process 

const Shorts = () => {
    const contentRef = useRef(null);

  const [reels] = useState([
    {
      data: paths.vegnonveg,
      title: 'vegnonveg',
      thumbnail: '',
      logo: vegNonVegLogo,
      class: 'down _01',
      dimension: 'w-[37%] h-[19%]'
    },
    {
      data: paths.bgTribe_of_6,
      title: 'tribe Of 6',
      thumbnail: '',
      logo: TO6Logo,
      class: 'down',
      dimension: 'w-[84%]'
    },
    {
      data: paths.deme,
      title: 'Deme',
      thumbnail: '',
      logo: demeLogo,
      class: 'down',
      dimension: 'w-[84%]'
    },
    {
      data: paths.FormOfStyle,
      title: 'FormOfStyle',
      thumbnail: '',
      logo: ModishLogo,
      class: 'down',
      dimension: 'w-[50%] h-[22%]'
    },
    {
      data: paths.Mokodora,
      title: 'Mokobora',
      thumbnail: '',
      logo: MokobaraLogo,
      class: 'down _01',
      dimension: 'w-[55%]'
    },
    {
      data: paths.NishaXAsaya,
      title: 'NishaXAsaya',
      thumbnail: '',
      logo: AsayaLogo,
      class: 'up',
      dimension: 'w-[250%]'
    },
    {
      data: paths.Simba,
      title: 'Simba',
      thumbnail: '',
      logo: SimbaLogo,
      class: 'down',
      dimension: 'w-[55%] h-[12%]'
    },
    {
      data: paths.SpyK,
      title: 'SpyK',
      thumbnail: '',
      logo: SaykLogo,
      class: 'up',
      dimension: 'w-[48%] h-[11%]'
    },
    {
      data: paths.Keif,
      title: 'Keif',
      thumbnail: '',
      logo: keiflogo,
      class: 'down _01',
      dimension: 'w-[55%]'
    },
    {
      data: paths.Nail_Station,
      title: 'Nail_Station',
      thumbnail: '',
      logo: Nail_StationLogo,
      class: 'up',
      dimension: 'w-[61%] h-[11%]'
    },
    {
      data: paths.Bhavani,
      title: 'Bhavani',
      thumbnail: '',
      logo: SculpLogo,
      class: 'down',
      dimension: 'w-[40%] h-[15%]'
    },
    {
      data: paths.Dhahia,
      title: 'Dhahia',
      thumbnail: '',
      logo: DhahiaLogo,
      class: 'up',
      dimension: 'w-[90%] h-[15%]'
    },
    {
      data: paths.nothing,
      title: 'Nothing',
      thumbnail: '',
      logo: Nothing,
      class: 'down _01',
      dimension: 'w-[55%] h-[10%]'
    },
    {
      data: paths.Arnav_Personal,
      title: 'Arnav_Personal',
      thumbnail: '',
      logo: ArnavLogo,
      class: 'down _01',
      dimension: 'w-[50%]'
    },
    {
      data: paths.Acqua,
      title: 'Acqua',
      thumbnail: '',
      logo: AcquaLogo,
      class: 'down _01',
      dimension: 'w-[37%] h-[19%]'
    },
    {
      data: paths.Mello,
      title: 'Mello',
      thumbnail: '',
      logo: AtyabLogo,
      class: 'down _01',
      dimension: 'w-[65%]'
    },
  ])
  return (
    <section id='shorts' className={'section bg-white bg-cover h-auto'}>
      <div className='container mx-auto' ref={contentRef}>
        <div className='flex pt-36 flex-col items-center gap-x-24 text-center lg:text-left '>
        <motion.div 
        variants={fadeIn('up', 0.3)} initial="hidden"
        whileInView={'show'} viewport={{once: false, amount: 0.5}}
        className='text-block-commercial'>
          Featured Short-Form
        </motion.div>
        <div
        //  variants={fadeIn('right', 0.3)} initial="hidden"
        //  whileInView={'show'} viewport={{once: true, amount: 0.5}}
         className='scroll-container-v2'>
            <div className='socialmedia-container-mobile'>
              {
                reels.map((reelVideo, index)=> (
                  <div
                  key={index}
                  className={'socialmedia-card-01 group'+' down'}>
                    <div className='opacity-0 overlay'>
                      <div style={{ backgroundImage: `url(${reelVideo.logo})` }} className={'video-logo _3 '+reelVideo.dimension}> </div>
                      <div className='dark-bg'> </div>
                    </div>
                    <div className='videobg1 w-background-video w-background-video-atom'>
                      <ReactPlayer fallback={<div>Loading...</div>} playing loop muted playsInline={false} url={reelVideo.data} width={'100%'} height={'100%'}>
                        {/* <source src={reelVideo.data} type='video/mp4'></source> */}
                      </ReactPlayer>
                    </div>
                  </div>
                ))
              }
            </div>
          </div>
        </div>
        </div>
    </section>
  );
};

export default Shorts;
