import React from 'react';
// import components
import Socials from './Socials'
import logo from '../img/header/logo.png'
import MobileNav from './MobileNav';

// import Link
import { Link } from 'react-scroll';

const Header = () => {
  return (
  <header className='bg-ping-200 fixed w-full px-[30px] lg:px-[100px] z-30 h-[100px] lg:h-[100px] flex items-center'>
    <div className='flex flex-col lg:flex-row items-center w-full justify-between'>
    {/* <Link to={'/'} className='max-w-[50px]'>
        <img src={New_Logo} alt='' />
      </Link> */}
      {/* nav - initially hidden - show on desktop mode */}
      <nav className='hidden lg:flex gap-x-12 font-semibold'>
      <Link to='home'
            activeClass='active'
            smooth={true}
            spy={true}
            offset={-30} className='cursor-pointer text-[#000000] text-[22px] hover:text-primary transition'>
        Home
      </Link>
      {/* <Link to={'/portfolio'} className='text-[#ffffff] text-[22px] hover:text-primary transition'>
        Shorts
      </Link> */}
      <Link to='shorts'
            activeClass='active'
            smooth={true}
            spy={true} className='cursor-pointer text-[#000000] text-[22px] hover:text-primary transition'>
        Shorts
      </Link>
      <Link to='work'
            activeClass='active'
            smooth={true}
            spy={true}
            offset={-30} className='cursor-pointer text-[#000000] text-[22px] hover:text-primary transition'>
        Work
      </Link>
      <Link to='about'
            activeClass='active'
            smooth={true}
            spy={true}
            offset={-30}  className='cursor-pointer text-[#000000] text-[22px] hover:text-primary transition'>
        About
      </Link>
      <Link to='contact'
            activeClass='active'
            smooth={true}
            spy={true}
            offset={-20}  className='cursor-pointer text-[#000000] text-[22px] hover:text-primary transition'>
        Contact
      </Link>
      </nav>
      {/* logo */}
      <Link to={'/g_portfolio'} className='max-w-[50px]'>
        <img src={logo} alt='' loading='lazy' />
      </Link>
    </div>
     {/* socials */}
     {/* <Socials /> */}
     {/* mobile nav */}
     <MobileNav />
  </header>
  );
};

export default Header;
