import React, { useRef } from 'react';
import g from '../img/contact/g.png'
// import  motion
import { motion } from 'framer-motion';
// import transition
import { transition1 } from '../transitions';

import { fadeIn } from '../variants';

const Contact = () => {
  const ref = useRef();
  return <motion.section id='contact' ref={ref}
  initial={{opacity: 0, y: '100%'}}
  animate={{ opacity: 1, y: 0}}
  exit={{opacity: 0, y: '100%'}}
  transition={transition1}
  className='section bg-white bg-cover h-auto'>
    <div className='container mx-auto'>
      <div className='flex flex-col pt-36 lg:flex-row items-center justify-start gap-x-8 text-center lg:text-left'>
        {/* <motion.div 
        initial={{opacity: 0, y: '100%'}}
        animate={{ opacity: 1, y: 0}}
        exit={{opacity: 0, y: '100%'}}
        transition={transition1}
        className='hidden lg:flex bg-[#dfa9a9] absolute bottom-0 left-0 right-0 top-72 -z-10'></motion.div> */}
        <div className='lg:flex-1 lg:pt-32 px-4'>
          <motion.div 
           variants={fadeIn('up', 0.3)} initial="hidden"
           whileInView={'show'} viewport={{once: false, amount: 0.5}}
          className='h1'>Let's make magic</motion.div>
          {/* <p className='mb-4'>Feel free to contact.</p> */}
          {/* <p className='mb-12'>Weather you are looking or a director or end to end film production!</p> */}
          <motion.form 
          variants={fadeIn('right', 0.3)} initial="hidden"
          whileInView={'show'} viewport={{once: false, amount: 0.5}}
          className='flex flex-col gap-y-4'>
            <div className='flex gap-x-10'>
              <input className='outline-none border-b border-b-primary h-[60px] bg-transparent font-secondary w-full pl-3 
                placeholder:text-[#757879]'
                type='text'
                placeholder='Name / Company'>
              </input>
              <input className='outline-none border-b border-b-primary h-[60px] bg-transparent font-secondary w-full pl-3 
                placeholder:text-[#757879]'
                type='text'
                placeholder='Your email address'>
              </input>
            </div>
            <div className='flex gap-x-10'>
            <input className='outline-none border-b border-b-primary h-[60px] bg-transparent font-secondary w-full pl-3 
                placeholder:text-[#757879]'
                type='text'
                placeholder='Phone'>
              </input>
              <input className='outline-none border-b border-b-primary h-[60px] bg-transparent font-secondary w-full pl-3 
                placeholder:text-[#757879]'
                type='text'
                placeholder='How did you hear about us?'>
              </input>
            </div>
            <input className='outline-none border-b border-b-primary h-[60px] bg-transparent font-secondary w-full pl-3 
                placeholder:text-[#757879]'
                type='text'
                placeholder='Your message'>
            </input>
            <button className='btn mb-[30px] mx-auto lg:mx-0 self-start'>
                    sent it
              </button>
          </motion.form>
        </div>
        <motion.div 
        variants={fadeIn('right', 0.3)} initial="hidden"
        whileInView={'show'} viewport={{once: false, amount: 0.5}}
        className='lg:flex-1'>
          <img src={g} className='lg:max-w-[100%]' alt='' loading='lazy'/>
        </motion.div>
      </div>
    </div>
    
  </motion.section>;
};

export default Contact;
