import React, { useState } from 'react';

import { IoMdClose } from 'react-icons/io';
import { CgMenuRight } from 'react-icons/cg';

import { Link } from 'react-scroll';
import { motion } from 'framer-motion';

const menuVariants = {
  hidden: {
    x: '100%'
  },
  show: {
    x: 0,
    transition: {
      ease: [0.6, 0.01, -0.05, 0.9],
    }
  }
}
 
const MobileNav = () => {
  const [openMenu, setOpenMenu] = useState(false);

  return (<nav className='text-primary xl:hidden '>
    {/* nav open button */}
    <div  onClick={() => setOpenMenu(true)} className='text-3xl cursor-pointer'>
      <CgMenuRight />
    </div>
    {/* menu */}
    <motion.div
    variants={menuVariants}
    initial='hidden'
    animate={openMenu ? 'show' : ''}
    className='bg-white shadow-2xl w-full absolute top-0 right-0 h-screen z-20'>
      {/* icon */}
      <div onClick={() => setOpenMenu(false)} className='text-4xl absolute z-30 left-4 top-14 text-primary cursor-pointer'>
        <IoMdClose />
      </div>
      {/* menu list */}
      <ul className='h-full w-full flex flex-col justify-center items-center gap-y-8 text-primary font-primary font-bold text-3xl'>
        <li>
          <Link  to='home'
            activeClass='active'
            smooth={true}
            spy={true}
            offset={-200} >Home</Link>
        </li>
        <li>
          <Link to='work'
            activeClass='active'
            smooth={true}
            spy={true}
            offset={-200} >Work</Link>
        </li>
        <li>
          <Link to='about'
            activeClass='active'
            smooth={true}
            spy={true}
            offset={-30} >About</Link>
        </li>
        <li>
          <Link to='contact'
            activeClass='active'
            smooth={true}
            spy={true}
            offset={-20} >Contact</Link>
        </li>
      </ul>
    </motion.div>
  </nav>);
};

export default MobileNav;
